const { chromium } = require('/home/lane/rblx/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/google-chrome',
    args: ['--enable-unsafe-swiftshader'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const u = 'face_' + Math.random().toString(36).slice(2, 6);
  await page.goto('http://localhost:3001');
  await page.click('#tab-register');
  await page.fill('#auth-user', u);
  await page.fill('#auth-pass', 'test1234');
  await page.click('#auth-go');
  await page.waitForSelector('.hero');
  await page.goto('http://localhost:3001/#/avatar');
  await page.waitForSelector('.avatar-preview canvas');
  await page.waitForTimeout(2500); // let it rotate to show the face
  await page.screenshot({ path: '/tmp/glint-shots/11-avatar-face.png' });
  // also in-game with the face visible: rotate camera to front
  const g = await (await fetch('http://localhost:3001/api/games')).json();
  await page.goto('http://localhost:3001/#/play/' + g.games[0].id);
  await page.waitForSelector('#game-root canvas');
  await page.waitForTimeout(2000);
  // drag to spin camera to the front of the character
  await page.mouse.move(640, 400); await page.mouse.down();
  await page.mouse.move(940, 380, { steps: 10 }); await page.mouse.up();
  await page.waitForTimeout(800);
  await page.screenshot({ path: '/tmp/glint-shots/12-ingame-face.png' });
  await browser.close();
  console.log('done');
})();
EOF
